insert into public.products (sku, slug, name, brand, category_id, subcategory, features, specs, colours,
  image_path, mrp, sell_price, price_basis, moq, branding_possible, delivery_note, ready_stock, under_production, status)
select r->>'sku', r->>'slug', r->>'name', r->>'brand', c.id, r->>'subcategory',
  array(select jsonb_array_elements_text(r->'features')), r->'specs',
  array(select jsonb_array_elements_text(r->'colours')), r->>'image_path',
  (r->>'mrp')::numeric, (r->>'sell_price')::numeric, (r->>'price_basis')::public.price_basis,
  (r->>'moq')::int, (r->>'branding_possible')::boolean, r->>'delivery_note',
  (r->>'ready_stock')::int, (r->>'under_production')::boolean, 'review'
from seed_rows join public.categories c on c.name = r->>'category'
on conflict (sku) do nothing;

insert into public.product_internal (product_id)
select p.id from seed_rows join public.products p on p.sku = r->>'sku'
on conflict (product_id) do nothing;


insert into public.product_collections (product_id, collection_id)
select p.id, col.id from seed_rows
join public.products p on p.sku = r->>'sku'
cross join lateral jsonb_array_elements_text(r->'collections') as cn(name)
join public.collections col on col.name = cn.name
on conflict do nothing;
commit;
